window.ScripturaLexicons.BDAG_PART_0201 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-01\" data-source=\"BDAG\" data-search=\"Κέσκος remissão ver Κέστος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κέσκος</td><td>remissão</td><td>ver Κέστος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-02\" data-source=\"BDAG\" data-search=\"Κέστος, ου nome próprio Cesto; nome de um centurião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κέστος, ου</td><td>nome próprio</td><td>Cesto; nome de um centurião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-03\" data-source=\"BDAG\" data-search=\"κεφάλαιον, ου, τό substantivo neutro ponto principal; resumo; capital BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφάλαιον, ου, τό</td><td>substantivo neutro</td><td>ponto principal; resumo; capital</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-04\" data-source=\"BDAG\" data-search=\"κεφαλαιόω verbo completar pecados; golpear na cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφαλαιόω</td><td>verbo</td><td>completar pecados; golpear na cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-05\" data-source=\"BDAG\" data-search=\"κεφαλή, ῆς, ἡ substantivo feminino cabeça; autoridade; extremidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφαλή, ῆς, ἡ</td><td>substantivo feminino</td><td>cabeça; autoridade; extremidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-06\" data-source=\"BDAG\" data-search=\"κεφαλιόω verbo golpear na cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφαλιόω</td><td>verbo</td><td>golpear na cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-07\" data-source=\"BDAG\" data-search=\"κεφαλίς, ίδος, ἡ substantivo feminino rolo de livro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφαλίς, ίδος, ἡ</td><td>substantivo feminino</td><td>rolo de livro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-08\" data-source=\"BDAG\" data-search=\"κεφαλοδέσμιον, ου, το substantivo neutro faixa para a cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κεφαλοδέσμιον, ου, το</td><td>substantivo neutro</td><td>faixa para a cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-09\" data-source=\"BDAG\" data-search=\"κέχρημαι remissão ver χράομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κέχρημαι</td><td>remissão</td><td>ver χράομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-10\" data-source=\"BDAG\" data-search=\"κηδεύω verbo cuidar de cadáver; sepultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κηδεύω</td><td>verbo</td><td>cuidar de cadáver; sepultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-11\" data-source=\"BDAG\" data-search=\"κημόω verbo pôr focinheira; amordaçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κημόω</td><td>verbo</td><td>pôr focinheira; amordaçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-12\" data-source=\"BDAG\" data-search=\"κῆνσος, ου, ὁ substantivo masculino imposto de capitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κῆνσος, ου, ὁ</td><td>substantivo masculino</td><td>imposto de capitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-13\" data-source=\"BDAG\" data-search=\"κῆπος, ου, ὁ substantivo masculino jardim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κῆπος, ου, ὁ</td><td>substantivo masculino</td><td>jardim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-14\" data-source=\"BDAG\" data-search=\"κηπουρός, οῦ, ὁ substantivo masculino jardineiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κηπουρός, οῦ, ὁ</td><td>substantivo masculino</td><td>jardineiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-15\" data-source=\"BDAG\" data-search=\"κηρίον, ου, τό substantivo neutro cera; favo de mel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κηρίον, ου, τό</td><td>substantivo neutro</td><td>cera; favo de mel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-16\" data-source=\"BDAG\" data-search=\"κήρυγμα, ατος, τό substantivo neutro proclamação; anúncio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κήρυγμα, ατος, τό</td><td>substantivo neutro</td><td>proclamação; anúncio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-17\" data-source=\"BDAG\" data-search=\"κῆρυξ, υκος, ὁ substantivo masculino arauto; proclamador; concha-trombeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κῆρυξ, υκος, ὁ</td><td>substantivo masculino</td><td>arauto; proclamador; concha-trombeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-18\" data-source=\"BDAG\" data-search=\"κηρύσσω verbo anunciar; proclamar; pregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κηρύσσω</td><td>verbo</td><td>anunciar; proclamar; pregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-19\" data-source=\"BDAG\" data-search=\"κῆτος, ους, τό substantivo neutro monstro marinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κῆτος, ους, τό</td><td>substantivo neutro</td><td>monstro marinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0201-20\" data-source=\"BDAG\" data-search=\"Κηφᾶς, ᾶ, ὁ nome próprio Cefas; sobrenome aramaico de Simão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κηφᾶς, ᾶ, ὁ</td><td>nome próprio</td><td>Cefas; sobrenome aramaico de Simão</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0201-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κέσκος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">Κέσκος</span> veja <span class=\"greek\">Κέστος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κέστος, ου</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κέστος</span>, <span class=\"greek\">ου</span>, nome romano, Thesaurus-Onomasticon II 356, 3ff: Cesto, um centurião, AcPl Ha 9, 18 (nome conforme Aa I 112, 5, [<span class=\"greek\">Κε</span>]<span class=\"greek\">σκῳ</span> no papiro; CSchmidt lê <span class=\"greek\">Κέσκος</span> também na lacuna de AcPl Ha 9, 30 = Aa I 114, 1).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφάλαιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφάλαιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κεφαλή</span>; Pind.+; inscrições, papiros, LXX; TestSol 12:3 P): em nossa literatura, o adjetivo <span class=\"greek\">κεφάλαιος</span>, -<span class=\"greek\">α</span>, -<span class=\"greek\">ον</span> somente é empregado como substantivo. ① Enunciado breve sobre algum assunto ou tema: ponto principal, aspecto essencial (Thu. 4, 50, 2; Isocr. 4, 149 <span class=\"greek\">κ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">εἰρημένων</span>; Pla., Phd. 44, 95b; Demosth. 13, 36; Epict. 1, 24, 20; POxy 67, 18; Philo, Leg. All. 2, 102; Jos., C. Ap. 1, 219, Ant. 17, 93; Just.; Tat. 51, 4; Ath., R. 20 p. 73, 16), Hv 5:5. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λεγομένοις</span>, o ponto principal do que foi dito (é este), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:1</a> (Menand., Georg. 75 <span class=\"greek\">κ</span>. … <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">λόγου</span>; Menand. em Plut., Mor. 103d <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>; PKöln II, 114, 2–3 = ZPE 4, ’69, 192; cf. plural em Pind., P. 4, 116).—Resumo, sinopse (restrita aos pontos principais): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κεφαλαίῳ</span>, em resumo, brevemente (incerto em Aristot., EN 1107b, 14; de outro modo, quer <span class=\"greek\">ἐν</span> <span class=\"greek\">κεφαλαίῳ</span>, X., Cyr. 6, 3, 18; Appian, Bell. Civ. 4, 93 §388 <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἰπεῖν</span>; PLips 105, 35; POxy 515, 6 e outros papiros; quer <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κεφαλαίου</span>, Polyb. 1, 65, 5; PTebt 24, 52; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κεφαλαίων</span>, Just., D. 85, 4; Tat. 31, 4), MPol 20:1. ② Bens acumulados, em oposição a juros ou rendimentos: ‘capital’ (Pla., Demosth., inscrições, papiros); daí, quantia de dinheiro em geral (Artem. 1, 17 p. 21, 19; 1, 35 p. 36, 17 e 37, 16; GDI 2503, 14 [Delfos]; Cyr.-Ins. 132; BGU 1200, 17 [I a.C.] <span class=\"greek\">οὐ</span> <span class=\"greek\">μικρῷ</span> <span class=\"greek\">κεφαλαίῳ</span>; POxy 268, 7; mais exemplos em New Docs 3 nº 43; Lev 5:24; Num 5:7; 31:26; EpArist 24; Jos., Ant. 12, 30; 155): <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πολιτείαν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἐκτησάμην</span>, adquiri esta cidadania por uma grande quantia de dinheiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:28</a>.—DELG s.v. <span class=\"greek\">κεφαλή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφαλαιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφαλαιόω</span> (veja <span class=\"greek\">κεφάλαιον</span>; Thu. e outros; Philod., <span class=\"greek\">Οἰκ</span>. col. 7, 40 Jensen; Diog. L. 7, 126; ‘resumir’ etc.). ① Completar a medida dos pecados, B 5:11, variante de leitura. ② Sobre agressão física, literalmente ‘golpear na cabeça’: tratar brutalmente, uso sem paralelos, talvez imagem coloquial referente a uma surra completa (cf., por exemplo, nosso ‘acabar com’ no sentido de destruir), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:4</a>, variante de leitura; ou talvez seja preferível (B-D-F § 108, 1; Mlt-H. 395) <span class=\"greek\">κεφαλιόω</span>, veja esse verbete, embora esta última forma seja de resto desconhecida. Veja VTaylor, Comm. ’66, comentário à passagem.—DELG s.v. <span class=\"greek\">κεφαλή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφαλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφαλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom.+), geralmente ‘cabeça’. ① Parte do corpo que contém o cérebro: cabeça. ⓐ De seres humanos, animais e seres transcendentes. Humanos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:36</a> (sobre jurar pela cabeça, veja Athen. 2, 72, 66c; Test12Patr; PGM 4, 1917; cf. Juvenal, Satires 6, 16f); 6:17; 14:8, 11; 26:7; 27:29f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:24f</a>, 27f; 14:3; 15:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:9</a>; 19:2; 20:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:4b</a> (JMurphy-O’Connor, CBQ 42, ’80, 485 [bibliografia] ‘sua cabeça’ = ‘ele próprio’), 5ab, 7, 10; 12:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:19</a> (cf. Josh 7:6; La 2:10); 1 Cl 37:5; 56:5 (Ps 140:5); B 13:5 (Gen 48:14); Hm 11:20; Papias (3:2 [não g e h]); GJs 2:4; 9:1; AcPl Ha 11, 1.—Animais: B 7:8 (acerca do bode expiatório, Lev 16; cf. versículo 21).—Nas representações apocalípticas relacionadas a figuras humanas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:14</a>; 4:4; 9:7 12:1; 14:14; 19:12; com animais: 9:7, 17, 19; 12:3 (veja <span class=\"greek\">δράκων</span>); 13:1, 3; 17:3, 7, 9 (cf. Ael. Aristid. 50, 50 K. = 26 p. 517 D.: <span class=\"greek\">ὤφθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἕδος</span> [de Asclépio] <span class=\"greek\">τρεῖς</span> <span class=\"greek\">κεφαλὰς</span> <span class=\"greek\">ἔχον</span>. Uma pessoa vê a si mesma num sonho dotada de várias cabeças, Artem. 1, 35 p. 37, 14: <span class=\"greek\">δύο</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κεφαλὰς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τρεῖς</span>. Também o cão de muitas cabeças Cérbero, do mundo inferior, em Hesiod, Theog. 311 e outras passagens, bem como Heraclit. Sto. 33 p. 49, 14); Hv 4, 1, 6; 10; de anjos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a>.—Os cabelos da cabeça (Philo, Leg. ad Gai. 223), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38</a>, 44, variante de leitura; 12:7; 21:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κλίνειν</span>, reclinar a cabeça para dormir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:58</a>. Semelhantemente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:30</a> (veja Hdb. ad loc.). <span class=\"greek\">κινεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. (veja <span class=\"greek\">κινέω</span> 2a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:29</a>; 1 Cl 16:16 (Ps 21:8); <span class=\"greek\">ἐπαίρειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. (veja <span class=\"greek\">ἐπαίρω</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:28</a>; tosquiar a cabeça, isto é, cortar o cabelo como forma de voto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a>; cf. 18:18. Acerca do batismo, <span class=\"greek\">ἔκχεον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">τρὶς</span> <span class=\"greek\">ὕδωρ</span>, D 7:3. Acerca da unção da cabeça de Jesus, IEph 17:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">ἔχειν</span>, ter (algo) sobre a cabeça (veja <span class=\"greek\">κατά</span> A 1a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:4a</a>; também com especificação do objeto: <span class=\"greek\">ἐπὶ</span> com genitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:14</a>; Hv 4, 1, 10; ou <span class=\"greek\">εἰς</span>, 4, 3, 1. <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., acima de sua cabeça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:37</a>. Também <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>. (<span class=\"greek\">ἀστὴρ</span>) <span class=\"greek\">ἔστη</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδίου</span>, (a estrela) parou sobre a cabeça do menino, GJs 21:3 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>).—Expressão conhecida do AT: <span class=\"greek\">ἄνθρακας</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">σωρεύειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:20</a> (veja <span class=\"greek\">ἄνθραξ</span>). Fórmula de maldição: <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑμῶν</span>, vosso sangue sobre vossas próprias cabeças (veja <span class=\"greek\">αἷμα</span> 2a e cf. Demosth., Ep. 4, 10 <span class=\"greek\">τ</span>. <span class=\"greek\">ἄδικον</span> <span class=\"greek\">βλασφημίαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λέγοντι</span> <span class=\"greek\">τρέπουσι</span>; 6, 1; Maximus Tyr. 5, 1d; Aesop, Fab. 206 P. = 372 H. //313 Ch.//222 H-H. <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">θέλεις</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σῇ</span> <span class=\"greek\">κεφαλῇ</span> <span class=\"greek\">γένοιτο</span>; Phalaris, Ep. 102 <span class=\"greek\">εἰς</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">σοί</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σῷ</span> <span class=\"greek\">γένει</span>) = sois responsáveis pela vossa própria destruição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:6</a>; cf. GPt 5:17. ⓑ Em sentido figurado: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔκλινας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κραταιὰν</span> <span class=\"greek\">χεῖραν</span>, não inclinaste a cabeça sob a poderosa mão (de Deus), GJs 15:4. De pessoas (Plut., Galba 1054 [4, 3] G. como <span class=\"greek\">κ</span>. <span class=\"greek\">ἰσχυρῷ</span> <span class=\"greek\">σώματι</span>, a saber, dos territórios gálatas): Cristo, a <span class=\"greek\">κ</span>. da <span class=\"greek\">ἐκκλησία</span>, concebida como um <span class=\"greek\">σῶμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:18</a>; cf. 2:19 (Artem. 2, 9 p. 92, 25 <span class=\"greek\">ἡ</span> <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">ὑπερέχει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">σώματος</span>; escólio sobre Nicander, Alexiph. 215 <span class=\"greek\">ἡ</span> <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">συνέχει</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>); Cristo e os cristãos como cabeça e membros, ITr 11:2 (SBedale, JTS 5, ’54, 211–15; New Docs 3, 45f [bibliografia]; não ‘fonte’: JFitzmyer, NTS 35, ’89, 503–11). Veja acepção 2a. ② Ser de posição elevada, cabeça, em sentido figurado (acerca de Asclépio, IG II 2, 4514, 6; na especulação gnóstica: Iren. 1, 5, 3 [Harv. I 45, 13]. <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ἄρχων</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>, Hippol., Ref. 7, 23, 3). ⓐ Quanto a seres vivos, para denotar posição superior (cf. Artem. 4, 24 p. 218, 8, <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. é o símbolo do pai; Judg 11:11; 2 Km 22:44): cabeça (Zosimus de Ascalom [500 d.C.] saúda Demosth. como mestre: <span class=\"greek\">ὦ</span> <span class=\"greek\">θεία</span> <span class=\"greek\">κεφαλή</span> [Biogr. p. 297]); do pai como cabeça da família, Hs 7, 3; do marido em relação à mulher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:3b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:23a</a>. De Cristo em relação à comunidade cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:15</a>; 5:23b. Mas Cristo é cabeça não só do corpo dos cristãos, como de todo o universo: <span class=\"greek\">κ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πάντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:22</a>; e de cada poder cósmico, <span class=\"greek\">κ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξουσίας</span>, cabeça de todo principado e autoridade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:10</a>. A influência divina sobre o mundo resulta na série (sobre o afastamento crescente de Deus com efeitos correspondentes, cf. Ps.-Aristot., De Mundo 6, 4): Deus, a <span class=\"greek\">κ</span>. de Cristo; Cristo, a <span class=\"greek\">κ</span>. do homem; o homem, a <span class=\"greek\">κ</span>. da mulher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:3c</a>ab (veja <span class=\"greek\">γυνή</span> 1). JFitzmyer, Int 47, ’93, 52–59. ⓑ Quanto a coisas, parte mais alta, extremidade, ponta, fim (Pappus de Alexandria, matemático [IV d.C.], no 8º livro [ed. CGerhardt 1871 p. 379 <span class=\"greek\">τῇ</span> <span class=\"greek\">κεφαλῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κοχλίου</span> = na ponta do parafuso; Judg 9:25; En 17:2; Jos., Bell. 2, 48, Ant. 3, 146; frequentemente nos papiros acerca de lotes de terreno): <span class=\"greek\">κ</span>. <span class=\"greek\">γωνίας</span>, pedra angular (assim M‘Neile, Mt, comentário à passagem; REB, pedra angular [principal]; e, com a apropriada omissão da tradução alternativa em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a> na margem da NEB; desse modo, a pedra angular constitui a extensão mais distante [cf. PFlor 50, 83] do ângulo, embora JJeremias, <span class=\"greek\">Αγγελος</span> I 1925, 65–70, ZNW 29, 1930, 264–80, TW IV 277–79, pense na pedra de remate acima da porta; assim também OMichel, TW IV 892, V 129 [diferentemente em 151]; KSchelkle, RAC I 233f; RMcKelvey, NTS 8, ’62, 352–59 [bibliografia 353 nota 1–3]. Veja HGressmann, PJ 6, 1910, 38–45; GWhitaker, Exp., 8ª série, 22, 1921, 470ff. Para outra opinião, veja a bibliografia no verbete <span class=\"greek\">ἀκρογωνιαῖος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:17</a> (sobre essas três passagens, veja JDerrett, TU 102, ’68, 180–86); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a> (Selwyn, comentário à passagem: ‘a noção expressa é de extremidade, não de altura’); B 6:4 (todas segundo Ps 117:22).—<span class=\"greek\">κ</span>. = capital (cidade) (Appian, Illyr. 19 §54), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:12</a> D (mas ‘cidade fronteiriça’, AClark, Acts of the Apostles ’33, 362–65, e JLarsen, CTM 17, ’46, 123–25).—B. 212. Schmidt, Syn. I 361–69. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφαλιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφαλιόω</span>, 1º aoristo <span class=\"greek\">ἐκεφαλίωσα</span> (Phryn. 95 Lob.; B-D-F § 108, 1; Mlt-H. 395): golpear na cabeça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:4</a> (variante de leitura <span class=\"greek\">κεφαλαιόω</span> [veja esse verbete]).—GBjörck, ConNeot 1, ’36, 1–4: ‘arruinar, matar de uma vez’.—Field, Notes 36f.—DELG s.v. <span class=\"greek\">κεφαλή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφαλίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφαλίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (em vários significados, Aristot. e outros; PCol IV, 108, 1 [III a.C.]; PLond III, verso 755, 6 p. 222 [IV d.C.]; LXX; EpArist 68; Philo, Mos. 2, 77; Jos., Ant. 12, 73 [conforme EpArist]), diminutivo de <span class=\"greek\">κεφαλή</span>, literalmente ‘cabecinha’; em nossa literatura, apenas uma ocorrência, modelada segundo o AT (Ezk 2:9) e numa citação de Ps 39:8: <span class=\"greek\">κ</span>. <span class=\"greek\">βιβλίου</span>, rolo de um livro (veja TBirt, RhM n.s. 62, 1907, 488; VGardthausen, Griech. Paläographie 2 I 1911, 141), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:7</a>.—DELG s.v. <span class=\"greek\">κεφαλή</span>. M-M.—OMichel, KEK ’75, 337.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κεφαλοδέσμιον, ου, το</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κεφαλοδέσμιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">το</span> (de resto atestado somente desde IV d.C.): faixa para a cabeça, GJs 2:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κέχρημαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">κέχρημαι</span> veja <span class=\"greek\">χράομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κηδεύω</span>, infinitivo de 1º aoristo <span class=\"greek\">κηδεῦσαι</span> (Trag. e outros; inscrições, papiros): ocupar-se de um cadáver, cuidar dele, sepultar (Soph., El. 1141; Polyb. 5, 10, 4; IG XIV, 1860; ISmyrna McCabe 421, 6; Boffo, Iscrizioni nº 39, 8 p. 320, 8 [SEG VIII, 13]; PParis 18b, 4; PLond III, 932, 10 p. 149 [211 d.C.]; TestAbr A 20 p. 103, 22 [Stone p. 54] <span class=\"greek\">ἐκήδευσαν</span>; TestJob 39:10 <span class=\"greek\">κεκήδευκα</span>; ParJer; ApcEsdr 7:15 p. 33, 1 Tdf.; ApcMos; Philo, Migr. Abr. 159; Jos., Ant. 3, 262; 9, 227), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:29</a>, variante de leitura.—DELG s.v. <span class=\"greek\">κήδω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κημόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κημόω</span>, futuro <span class=\"greek\">κημώσω</span>: pôr focinheira, amordaçar (X., R. Equ. 5, 3), <span class=\"greek\">βοῦν</span> <span class=\"greek\">ἀλοῶντα</span>, um boi que debulha os grãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:9</a> (variante de leitura <span class=\"greek\">φιμόω</span>, veja esse verbete); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:18</a> D.—DELG s.v. <span class=\"greek\">κημός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῆνσος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κῆνσος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (empréstimo do latim census, também no rabínico, atestável em grego desde I a.C. [inscrição: AnnBSA 12, 1905/6, p. 178]. Cf. BGU 917, 6; PAmh 83, 2; outras inscrições e papiros em New Docs 3, 70f): imposto por cabeça (em contraste com ‘imposto sobre mercadorias’, veja <span class=\"greek\">τέλος</span> 5): tributo, imposto de capitação; <span class=\"greek\">κῆνσον</span> <span class=\"greek\">διδόναι</span>, pagar o imposto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:14</a>; <span class=\"greek\">λαμβάνειν</span>, arrecadar impostos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:25</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">νόμισμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., a moeda com a qual se paga o imposto, 22:19 (cf. Hesychius <span class=\"greek\">κῆνσος</span>· <span class=\"greek\">εἶδος</span> <span class=\"greek\">νομίσματος</span>, <span class=\"greek\">ἐπικεφάλαιον</span>).—Pauly-W. III 1899, 1914ff; RAC II 961ff. Veja <span class=\"greek\">φόρος</span>.—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῆπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κῆπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; inscrições, papiros, LXX; Jos., Bell. 5, 410, Ant. 9, 227): jardim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:1</a>, 26; 19:41; GPt 6:24.—B. 490. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηπουρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κηπουρός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja o verbete anterior; também <span class=\"greek\">οὖρος</span>, ‘aquele que vigia’; Pla. e outros; Polyb. 18, 6, 4; Epict. 3, 5, 17; 24, 44f; Plut., Mor. 927b, Aratus 5, 5; 6, 3; 7, 3; SIG 120B, 6 [c. 400 a.C. <span class=\"greek\">κηπορός</span>]; MAMA III, 13; PSI 336, 6; 13 [257/256 a.C.]; BGU 111 I, 21; PLips 97 XIV, 3): jardineiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:15</a> (NWyatt, ZNW 81, ’90, 21–38, tema do paraíso).—DELG s.v. <span class=\"greek\">κῆπος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηρίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κηρίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hes.+; inscrições, papiros, LXX; JosAs; Jos., Ant. 6, 118; 126): cera, favo de mel, B 6:6 (Ps 117:12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:42</a>, variante de leitura (cf. JosAs 16:1ff; veja <span class=\"greek\">μελίσσιος</span>).—DELG s.v. <span class=\"greek\">κηρός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κήρυγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κήρυγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κηρύσσω</span> e o verbete seguinte). ① Anúncio oficial, proclamação, quanto ao conteúdo da proclamação de um arauto (assim Soph., Hdt.+; inscrições, PPetr III, 125, 9; PHamb 29, 10; LXX; Philo, Agr. 117 e outras passagens; Jos., Ant. 10, 236); de uma convocação para reunião: <span class=\"greek\">κηρύγματι</span> <span class=\"greek\">καλεῖν</span>, convocar por proclamação, B 12:6. Em outros lugares de nossa literatura: ② Declaração pública, algo proclamado em voz alta, proclamação, por um arauto enviado por Deus (cf. Herm. Wr. 4, 4; Himerius, Or. 69 [= Or. 22], 7 e 8: o orador dá a conhecer o <span class=\"greek\">κήρυγμα</span> aos <span class=\"greek\">μύσται</span> e <span class=\"greek\">ἐπόπται</span>; ParJer 7:16 [códice C] <span class=\"greek\">τοῦ</span> <span class=\"greek\">καλοῦ</span> <span class=\"greek\">κηρύγματος</span>; ApcEsdr 5:17 p. 30, 17 Tdf. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὑψηλῷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κηρύγματι</span>, ‘em tom majestoso’; também Jon 3:2; Philo, Mos. 2, 167; 170; Jos., Bell. 6, 288 <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κ</span>.; Ar. 15:2; Just.): quanto à proclamação profética, <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰωνᾶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:32</a> (<span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωνᾶν</span>, Did., Gen. 185, 8). <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, proclamação acerca de Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:25</a>. Em uso absoluto, acerca da proclamação apostólica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:17</a>; Hs 8, 3, 2 (Did., Gen. 151, 14). <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span>, minha proclamação (do evangelho), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4</a>; cf. 15:14 (cf. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστόλων</span>, Iren. 3, 3, 3 [Harv. II 10, 8]; <span class=\"greek\">τῶν</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">μαθητῶν</span>, Hippol., Ref. 5, 8, 12; <span class=\"greek\">Χριστιανῶν</span>, Orig., C. Cels. 1, 7, 3). <span class=\"greek\">διδάσκαλοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, mestres da proclamação acerca do Filho de Deus, Hs 9, 15, 4. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span>, final breve de Mk (Polyaenus 4, 7, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλευθερίας</span>; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, Hippol., Ref. 7, 32, 6); <span class=\"greek\">σφραγὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., o selo da proclamação (do evangelho), isto é, o batismo, Hs 9, 16, 5. <span class=\"greek\">κήρυγμα</span> <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">ἐπιστεύθην</span> <span class=\"greek\">ἐγώ</span>, a proclamação que me foi confiada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>.—CDodd, The Apostolic Preaching and Its Developments ’36. KGoldammer, ZNW 48, ’57, 77–101; WBaird, JBL 76, ’57, 181–91.—DELG s.v. <span class=\"greek\">κῆρυξ</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῆρυξ, υκος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κῆρυξ</span>, <span class=\"greek\">υκος</span>, <span class=\"greek\">ὁ</span> (também <span class=\"greek\">κήρυξ</span>; sobre a acentuação segundo Herodian Gr., veja B-D-F § 13; Mlt-H. 57; PKatz, TLZ 83, ’58, 316 nota 6. Veja <span class=\"greek\">κηρύσσω</span> e o verbete anterior). ① Funcionário encarregado de fazer uma proclamação, arauto (Hom.+; inscrições, papiros, LXX; Philo, Agr. 112; Jos., Bell. 2, 624, Ant. 10, 75), MPol 12:1f; GJs 8:3. ② Aquele que faz declarações públicas, especialmente de natureza transcendente, arauto, proclamador (no uso dos cultos de mistérios: X., Hell. 2, 4, 20 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μυστῶν</span> <span class=\"greek\">κῆρυξ</span>; Philostrat., Vi. Soph. 2, 33, 4 <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἐλευσινίου</span> <span class=\"greek\">ἱεροῦ</span> <span class=\"greek\">κῆρυξ</span>; SIG 728B, 9 <span class=\"greek\">κῆρυξ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, 773, 5 <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀπόλλωνος</span>, 845, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱερῶν</span> <span class=\"greek\">κ</span>.; Just. [acerca de João Batista]; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, Tat. 17, 1 e Iren. 1, 15, 6 [Harv. I 155, 14]. Veja Poland, 395.—O cínico, como mensageiro enviado por Deus, chama a si mesmo de <span class=\"greek\">κ</span>.: Epict. 3, 22, 69; 3, 21, 13.—Herm. Wr. 4, 4. Cf. JosAs 14:2 <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">φωτὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">ἡμέρας</span> [acerca da estrela da manhã]; sol, lua e estrelas como <span class=\"greek\">κ</span>. e <span class=\"greek\">ἄγγελοι</span> de Deus, Orig., C. Cels. 5, 12, 38ff), arauto (de Deus), alguém que proclama; acerca de Noé: <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:5</a>. Acerca do apóstolo Paulo (com <span class=\"greek\">ἀπόστολος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:7</a>; (com <span class=\"greek\">ἀπόστολος</span> e <span class=\"greek\">διδάσκαλος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:11</a>. Igualmente acerca de Paulo, 1 Cl 5:6. ③ Concha-trombeta (Aristot., HA 5, 544, 546, 547 e outras passagens; Machon 133 em Athen. 8, 349c), concha marinha grande e pontiaguda, usada para torturar, MPol 2:4.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κηρύσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κηρύσσω</span>, imperfeito <span class=\"greek\">ἐκήρυσσον</span>; futuro <span class=\"greek\">κηρύξω</span>; 1º aoristo <span class=\"greek\">ἐκήρυξα</span>, infinitivo <span class=\"greek\">κηρύξαι</span> (também <span class=\"greek\">κηρῦξαι</span>, assim Tdf.); sobre a acentuação, veja B-D-F § 13; PKatz-Walters, The Text of the Septuagint, Cambridge ’73, 97); infinitivo perfeito <span class=\"greek\">κεκηρυχέναι</span> (Just., D. 49, 2). Na passiva: 1º futuro <span class=\"greek\">κηρυχθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκηρύχθην</span>; perfeito <span class=\"greek\">κεκήρυγμαι</span> (Just.) (veja os dois verbetes anteriores; Hom.+; inscrições, papiros, LXX; PsSol 11:1; TestLevi 2:10; GrBar 16:4 [-<span class=\"greek\">ττ</span>-]; Philo, Joseph.; empréstimo no rabínico; obras apologéticas, exceto Ar.). ① Fazer anúncio oficial, anunciar, dar a conhecer por meio de um arauto oficial ou alguém que exerce tal função (Maximus Tyr. 1, 6c <span class=\"greek\">κηρύττομαι</span> = sou anunciado pelo arauto), MPol 12:1, sobre o procônsul, que anunciou três vezes que Pol. confessara ser cristão.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:2</a>. ② Fazer declarações públicas, proclamar em voz alta. ⓐ Em geral, falar de, mencionar publicamente, com acusativo: <span class=\"greek\">κ</span>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, divulgar amplamente a notícia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>. A hospitalidade da igreja de Corinto, 1 Cl 1:2. Seguido de discurso indireto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:39</a>. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:36</a>.—Veja abaixo 2b <span class=\"greek\">β</span>. ⓑ Sobre proclamações de origem divina ou relacionadas à divindade (Epict. 3, 13, 12, acerca da paz dos sábios, que não se origina do imperador, mas é <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κεκηρυγμένη</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγου</span>. Sobre os mitos [reprováveis] dos gregos: <span class=\"greek\">ταῦτα</span> … <span class=\"greek\">οἱ</span> … <span class=\"greek\">συγγραφεῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιηταὶ</span> <span class=\"greek\">κ</span>., Theoph. Ant. 1, 9 [p. 78, 13]). <span class=\"greek\">α</span>. Sobre a proclamação ou os oráculos dos antigos profetas (Jo 2:1; 4:9; Jon 1:2; 3:2; Jos., Ant. 10, 117; Just., A I, 54, 2): <span class=\"greek\">Ἰωνᾶς</span> <span class=\"greek\">Νινευί</span>̈<span class=\"greek\">ταις</span> <span class=\"greek\">καταστροφὴν</span> <span class=\"greek\">ἐκήρυξεν</span>, 1 Cl 7:7 (Jonas como em Jos., Ant. 9, 214; Just., D. 107, 2f; Orig., C. Cels. 7, 57, 3); cf. versículo 6; 9:4 (Noé como em SibOr 1, 128); 17:1 (Elias e Eliseu, também Ezequiel); B 6:13 (<span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span>). <span class=\"greek\">προφήτας</span> [<span class=\"greek\">ἐξ</span>]<span class=\"greek\">έπεμψεν</span> <span class=\"greek\">κ</span>. … <span class=\"greek\">χριστὸν</span> <span class=\"greek\">Ἰησοῦν</span>, AcPl Ha 8, 17//Ox 1602, 19–21//BMM recto 21f. <span class=\"greek\">Ἰωνᾶς</span> … [<span class=\"greek\">ἵνα</span>] <span class=\"greek\">εἰς</span> <span class=\"greek\">Νεινεύη</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κηρύξῃ</span>, AcPl Cor 2:29. <span class=\"greek\">οἵτινες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπλανῆ</span> <span class=\"greek\">θεοσέβειαν</span> <span class=\"greek\">ἐκήρυσσον</span>, os quais proclamavam o modo infalível de reverenciar a Deus, 2:10. <span class=\"greek\">β</span>. Sobre proclamadores contemporâneos (POxy 1381, 35; 144 [II d.C.]: acerca das grandes obras dos deuses; Herm. Wr. 1, 27; 4, 4.—Philo, Agr. 112 <span class=\"greek\">κήρυξον</span> <span class=\"greek\">κήρυγμα</span> <span class=\"greek\">τοιοῦτον</span>. Veja <span class=\"greek\">κῆρυξ</span> 2.—Também sobre falsos profetas: Jos., Bell. 6, 285), a tradição mosaica e sua divulgação, a pregação de João Batista e a propagação da mensagem cristã no sentido mais amplo: <span class=\"greek\">Μωϋσῆν</span>, pregar (= promover a causa de) Moisés, isto é, a observância da lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:21</a>. <span class=\"greek\">περιτομήν</span>, proclamar a circuncisão, isto é, sua necessidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:11</a> (aqui e em 2a também é provável o significado ‘louvar publicamente’: X., Cyr. 8, 4, 4; Polyb. 30, 29, 6). <span class=\"greek\">κ</span>. <span class=\"greek\">μὴ</span> <span class=\"greek\">κλέπτειν</span>, investir verbalmente contra o roubo (= pregar: não roubar!), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:21</a>.—<span class=\"greek\">κ</span>. <span class=\"greek\">τι</span>, proclamar alguma coisa (<span class=\"greek\">ἕνα</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">παντοκράτορα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">μονογενῆ</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">κ</span>., Iren. 1, 9, 2 [Harv. I 82, 5]; <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄγνωστον</span> <span class=\"greek\">πατέρα</span>, 1, 26, 1 [Harv. I 211, 11]; Hippol., Ref. 1, Prol. 7; Did., Gen. 183, 6; 209, 13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:27</a>; na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>. <span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">δεκτόν</span>, 4:19 (cf. Is 61:1f). <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:2</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, a mensagem da fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:1</a>; 9:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:25</a>; 28:31. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:2</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:2</a>; B 5:9; GMary Ox 3525, 28; 32. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>; 9:35 (cf. <span class=\"greek\">τὸν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λόγον</span>, Orig., C. Cels. 3, 40, 20); <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Hs 9, 16, 5. Com dativo de pessoa (Hippol., Ref. 5, 26, 30), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:27</a> (sobre o tema do temido fracasso, veja APapathomas, NTS 43, ’97, 240); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:19</a> (CCranfield, ET 69, ’57/58, 369–72; veja bibliografia em <span class=\"greek\">πνεῦμα</span> 4c); GPt 10:41. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">συναγωγάς</span>, nas sinagogas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:44</a>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, alguma coisa a alguém (a respeito de Jesus, <span class=\"greek\">κ</span>. <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, Orig., C. Cels. 7, 57, 4; <span class=\"greek\">τὸ</span> <span class=\"greek\">κηρῦξαι</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, Did., Gen. 53, 13), 4:18; B 14:9 (ambas conforme Is 61:1). <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, alguma coisa a alguém: <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, Hs 9, 25, 2. Na passiva, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:10</a> (DBosch, Die Heidenmission in der Zukunftsschau Jesu ’59, 159–71); <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:14</a>; 26:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:23</a>.—<span class=\"greek\">βάπτισμα</span>, proclamar o batismo, isto é, sua necessidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:37</a>. <span class=\"greek\">ἐκηρύχθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σφραγὶς</span> <span class=\"greek\">αὕτη</span>, H 9, 16, 4. <span class=\"greek\">κηρυχθῆναι</span> … <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄφεσιν</span> <span class=\"greek\">ἁμαρτιῶν</span>, arrependimento para o perdão dos pecados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:47</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μετανοῶσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:12</a>. [<span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">τῶν</span>] <span class=\"greek\">κηρυσσόντων</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μετανοῆται</span> (leia-se: -<span class=\"greek\">ῆτε</span>), AcPl Ha 1, 17.—<span class=\"greek\">τινά</span> (<span class=\"greek\">τινι</span>), alguém (a alguém): <span class=\"greek\">Χριστόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:15</a>. <span class=\"greek\">Ἰησοῦν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:4</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">κηρύσσομεν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">κύριον</span>, não proclamamos a nós mesmos, mas a Cristo Jesus como Senhor, 4:5. Na passiva, <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> (<span class=\"greek\">Χριστός</span>) … <span class=\"greek\">ἐκηρύχθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>; cf. Hs 8, 3, 2; 9, 17, 1; Dg 11:3. <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span>, por intermédio de alguém (cf. Epict. 3, 13, 12): <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κηρυχθείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:19</a>. Com acréscimo que indica o conteúdo da proclamação, introduzido por <span class=\"greek\">ὅτι</span> (cf. Epict. 4, 5, 24): <span class=\"greek\">κ</span>. com acusativo seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:14</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:20</a>; na passiva, <span class=\"greek\">Χρ</span>. <span class=\"greek\">κηρύσσεται</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἐγήγερται</span>, Cristo é proclamado como ressuscitado dentre os mortos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τινί</span>, <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:42</a>; <span class=\"greek\">οὕτως</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:11</a>. O conteúdo da proclamação é introduzido por <span class=\"greek\">λέγων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:1f</a>; 10:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; cf. versículo 14; IPhld 7:2. Ao lado de <span class=\"greek\">λέγειν</span> com discurso direto (Epict. 4, 6, 23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:17</a>. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:38</a>; 3:14; 16:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:15</a>; 1 Cl 42:4; B 5:8 (proclamação de Jesus definida como ensino e realização de prodígios e sinais); 8:3. <span class=\"greek\">κηρύσσων</span>, proclamador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14</a>.—Veja bibliografia sob <span class=\"greek\">κήρυγμα</span>; também MGrumm, translating ke ̄ russo ̄ and Related Verbs: BT 21, ’70, 176–79.—B. 1478. DELG s.v. <span class=\"greek\">κῆρυξ</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κῆτος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κῆτος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e outros; Diod S 17, 41, 5 <span class=\"greek\">κῆτος</span> <span class=\"greek\">ἄπιστον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγεθος</span>; LXX; TestJud 21:7; TestSol 2:8; JosAs 12:10): monstro marinho (como o que tentou engolir Andrômeda: Eur., Andr. Fgm. 121; 145 TGF), acerca do peixe de Jonas (<span class=\"hebrew\">דָּג</span> <span class=\"hebrew\">גָּדוֹל</span>), <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κοιλίᾳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κήτους</span> (Jon 2:1; cf. 3 Macc 6:8; Jos., Ant. 9, 213), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a>; AcPlCor 2:29 (todos os detalhes provêm de Jon 2:1. Mas Tzetzes, no comentário a Lycophron 34, narra que Héracles permaneceu no ventre do <span class=\"greek\">κῆτος</span> durante três dias ao resgatar Hesíone). De um animal apocalíptico, Hv 4, 1, 6; 9.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0201-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κηφᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κηφᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\">כֵּיפָא</span> ‘rocha’): Cefas, sobrenome aramaico de Simão; a forma grega do sobrenome é <span class=\"greek\">Πέτρος</span> (veja a bibliografia em <span class=\"greek\">πέτρα</span> 1b e <span class=\"greek\">Πέτρος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:12</a>; 3:22; 9:5; 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:18</a>; 2:9, 11, 14; 1 Cl 47:3. <span class=\"greek\">Κ</span> = <span class=\"greek\">Πέτρος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:42</a> (veja JFitzmyer, To Advance the Gospel, ’81, 112–24).—M-M. EDNT. TW.</p></section></article>"};
